(function(){if(document.getElementById("alive-lp-css"))return;var s=document.createElement("style");s.id="alive-lp-css";s.textContent="/* Alive landing selector \u2014 \"What are we making?\" (28 Sep 2026)\n   Rendered straight onto the WordPress page (no iframe) so it uses the site's Gilroy.\n   Everything is scoped under #alive-lp so theme CSS and ours don't collide. */\n#alive-lp,#alive-lp *{box-sizing:border-box;}\n#alive-lp{--blue:#1b6dce;--blue-d:#1558a8;--ink:#3e3e3f;--tile:#e8eff7;\n  background:var(--blue);color:#fff;border-radius:24px;padding:30px 48px 40px;max-width:1312px;margin:0 auto;\n  font-family:Gilroy,Arial,sans-serif;font-weight:500;line-height:1.4;text-align:left;isolation:isolate;}\n#alive-lp .alp-logo{display:block;width:130px;height:54px;object-fit:contain;object-position:left center;margin:0 0 24px;}\n#alive-lp .alp-grid{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:48px;align-items:start;}\n#alive-lp h1{font:700 clamp(30px,3.3vw,46px)/1.04 Gilroy,Arial,sans-serif !important;letter-spacing:-1px;color:#fff !important;margin:0 0 24px;padding:0;text-transform:none;}\n#alive-lp .alp-lbl{display:block;font-size:16px;font-weight:500;color:#fff;margin:0 0 9px;}\n#alive-lp .alp-sec{margin:0 0 22px;}\n#alive-lp .alp-row{display:flex;gap:10px;}\n#alive-lp button{font-family:inherit;cursor:pointer;letter-spacing:normal;text-transform:none;box-shadow:none;margin:0;}\n#alive-lp button:focus-visible,#alive-lp input:focus-visible{outline:3px solid #e0dcd0;outline-offset:3px;}\n/* product tiles */\n#alive-lp .alp-tile{position:relative;flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;\n  background:var(--tile);border:3px solid transparent;border-radius:12px;padding:8px;color:var(--ink);font-weight:700;font-size:14px;min-height:122px;line-height:1.2;}\n#alive-lp .alp-tile img{width:100%;height:82px;object-fit:contain;mix-blend-mode:multiply;}\n#alive-lp .alp-tile[aria-checked=\"true\"]{background:#fff;border-color:#fff;color:var(--blue);}\n#alive-lp .alp-tile .alp-check{display:none;position:absolute;top:5px;right:5px;width:19px;height:19px;border-radius:50%;background:var(--blue);color:#fff;\n  font:700 12px/19px Arial,sans-serif;text-align:center;}\n#alive-lp .alp-tile[aria-checked=\"true\"] .alp-check{display:block;}\n#alive-lp .alp-tile:hover{filter:brightness(.98);}\n/* quantity */\n#alive-lp .alp-qrow{display:flex;align-items:center;gap:16px;font-size:14px;flex-wrap:wrap;}\n#alive-lp .alp-step{display:flex;height:50px;border:1px solid #fff;border-radius:9px;overflow:hidden;}\n#alive-lp .alp-step button{background:transparent;color:#fff;border:0;border-radius:0;padding:0;width:48px;min-height:48px;font-size:23px;line-height:1;}\n#alive-lp .alp-step button:disabled{opacity:.45;cursor:default;}\n#alive-lp .alp-step input{background:transparent !important;color:#fff !important;border:0 !important;border-left:1px solid rgba(255,255,255,.38) !important;\n  border-right:1px solid rgba(255,255,255,.38) !important;border-radius:0 !important;width:84px;min-width:0;padding:0 4px !important;margin:0;text-align:center;\n  font:700 21px/48px Gilroy,Arial,sans-serif;height:48px;-moz-appearance:textfield;appearance:textfield;box-shadow:none !important;}\n#alive-lp .alp-step input::-webkit-inner-spin-button,#alive-lp .alp-step input::-webkit-outer-spin-button{-webkit-appearance:none;margin:0;}\n#alive-lp .alp-step input[aria-invalid=\"true\"]{background:rgba(0,0,0,.18) !important;}\n/* decoration */\n#alive-lp .alp-deco{flex:1;min-width:0;display:flex;align-items:center;justify-content:center;min-height:48px;border:1px solid #fff;border-radius:9px;\n  background:transparent;color:#fff;font-size:15px;font-weight:700;padding:10px 8px;}\n#alive-lp .alp-deco[aria-checked=\"true\"]{background:#fff;color:var(--blue);}\n/* price */\n#alive-lp .alp-price{margin:0 0 18px;padding:14px 16px;border:1px solid rgba(255,255,255,.45);border-radius:12px;background:rgba(255,255,255,.1);\n  display:grid;grid-template-columns:1fr auto;gap:2px 16px;align-items:end;min-height:78px;}\n#alive-lp .alp-unit{font-size:30px;font-weight:700;letter-spacing:-.5px;line-height:1.05;font-variant-numeric:tabular-nums;}\n#alive-lp .alp-unit small{font-size:15px;font-weight:500;letter-spacing:0;opacity:.9;}\n#alive-lp .alp-total{text-align:right;font-size:15px;font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap;}\n#alive-lp .alp-total span{display:block;font-size:12px;font-weight:500;opacity:.85;}\n#alive-lp .alp-sub{grid-column:1 / -1;font-size:13px;opacity:.92;margin-top:6px;}\n#alive-lp .alp-sub b{font-weight:700;}\n#alive-lp .alp-nudge{background:none;border:0;padding:0;color:#fff;text-decoration:underline;text-underline-offset:3px;font-size:13px;font-weight:700;}\n#alive-lp .alp-price.loading .alp-unit,#alive-lp .alp-price.loading .alp-total{opacity:.5;}\n/* actions */\n#alive-lp .alp-go{display:flex;justify-content:space-between;align-items:center;width:100%;min-height:56px;padding:14px 20px;background:#fff;color:var(--blue);\n  border:0;border-radius:9px;font-size:19px;font-weight:700;line-height:1.3;}\n#alive-lp .alp-go span{font-size:25px;line-height:1;}\n#alive-lp .alp-go:hover{background:#f2f6fc;}\n#alive-lp .alp-up{display:flex;align-items:center;justify-content:center;gap:6px;flex-wrap:wrap;margin-top:8px;font-size:13px;}\n#alive-lp .alp-up button{color:#fff;background:transparent;border:0;text-decoration:underline;text-underline-offset:4px;min-height:44px;padding:8px 0;font-size:13px;font-weight:700;}\n#alive-lp .alp-err{color:#fff;background:#164b86;border:1px solid #fff;border-radius:8px;font-size:14px;margin:8px 0 0;padding:10px 12px;}\n#alive-lp .alp-perks{display:flex;justify-content:center;flex-wrap:wrap;gap:6px 16px;margin:10px 0 0;padding:0;list-style:none;font-size:12.5px;opacity:.95;}\n#alive-lp .alp-perks li{display:flex;align-items:center;gap:6px;margin:0;padding:0;}\n#alive-lp .alp-perks li:before{content:\"\\2713\";font-weight:700;}\n/* photo */\n#alive-lp .alp-fig{margin:0;display:flex;flex-direction:column;align-self:center;min-width:0;}\n#alive-lp .alp-photo{padding:14px;border-radius:18px;background:#fff;overflow:hidden;}\n#alive-lp .alp-photo img{width:100%;height:440px;object-fit:contain;display:block;}\n#alive-lp .alp-cap{text-align:center;color:#fff;font-size:12px;margin:12px 0 0;}\n#alive-lp [hidden]{display:none !important;}\n@media (max-width:760px){\n  #alive-lp{padding:24px 20px 24px;border-radius:24px;}\n  #alive-lp .alp-logo{width:112px;height:46px;margin-bottom:20px;}\n  #alive-lp .alp-grid{display:flex;flex-direction:column;gap:0;align-items:stretch;}\n  #alive-lp .alp-ctl{display:contents;}\n  #alive-lp h1{order:0;font-size:34px !important;margin-bottom:22px;}\n  #alive-lp .alp-products{order:1;}\n  #alive-lp .alp-fig{order:2;margin:0 0 22px;width:100%;}\n  #alive-lp .alp-photo{padding:10px;border-radius:12px;}\n  #alive-lp .alp-photo img{height:230px;}\n  #alive-lp .alp-cap{font-size:11px;margin-top:8px;}\n  #alive-lp .alp-qty{order:3;} #alive-lp .alp-decos{order:4;} #alive-lp .alp-price{order:5;} #alive-lp .alp-acts{order:6;}\n  #alive-lp .alp-tile{min-height:108px;padding:5px;font-size:13px;}\n  #alive-lp .alp-tile img{height:70px;}\n  #alive-lp .alp-row{gap:8px;}\n  #alive-lp .alp-qrow{gap:12px;font-size:13px;}\n  #alive-lp .alp-step input{width:68px;}\n  #alive-lp .alp-deco{font-size:14px;}\n  #alive-lp .alp-unit{font-size:26px;}\n  #alive-lp .alp-go{font-size:18px;}\n  #alive-lp .alp-up,#alive-lp .alp-up button{font-size:12px;}\n}\n@media (max-width:360px){ #alive-lp{padding:20px 14px 22px;} #alive-lp .alp-tile{font-size:12px;} }\n";(document.head||document.documentElement).appendChild(s);})();
/* Alive landing selector — "What are we making?" (28 Sep 2026)
   Three products, live prices from the same engine and catalog as the product page.
   Mounts into <div id="alive-lp"></div> on the WordPress page. The CTAs hand off to
   /insta-price/?style=..&color=Black&qty=..&method=..&intent=design|upload */
(function(){
  'use strict';
  var root = document.getElementById('alive-lp');
  if(!root || root.getAttribute('data-ready')) return;
  root.setAttribute('data-ready', '1');
  var E = window.AliveEngine;
  var BASE = 'https://aliveprintshop.github.io/PriceCalculator/';
  var CONFIG = {
    productPage: root.getAttribute('data-product-url') || 'https://aliveprintshop.com/insta-price/',
    min: 24,
    color: 'Black'
  };
  var PRODUCTS = [
    {key:'tshirt', label:'T Shirt', style:'NL6210', brand:'Next Level Apparel', noun:'shirt', img:'media/landing/shirt-black-crop.webp', methods:['sp','ht']},
    {key:'hoodie', label:'Hoodie',  style:'18500',  brand:'Gildan',             noun:'hoodie', img:'media/landing/hoodie-black-crop.webp', methods:['sp','em']},
    {key:'hat',    label:'Hat',     style:'31-069', brand:'OTTO CAP',           noun:'hat',    img:'https://s3-us-west-2.amazonaws.com/ottocap/media/products/otto/31-069/31-069-003-F.medium.jpg', methods:['em','ht']}
  ];
  var MLABEL = {sp:'Screen Print', em:'Embroidery', ht:'Full Color'};
  var MNOTE  = {sp:'1-color front print', em:'Embroidered front logo', ht:'Full-color front print'};
  var S = {p:0, qty:36, m:'sp', data:{}, err:''};

  function money(n){ return '$' + Number(n).toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2}); }
  function esc(s){ return String(s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  function cur(){ return PRODUCTS[S.p]; }
  function imgUrl(pr){ return /^https?:/.test(pr.img) ? pr.img : BASE + pr.img; }
  function track(name, params){
    try{ if(window.gtag) window.gtag('event', name, params); }catch(e){}
    try{ (window.dataLayer = window.dataLayer || []).push(Object.assign({event:name}, params)); }catch(e){}
  }

  /* ---- catalog: the same per-product files the product page reads ---- */
  function getJSON(url){ return fetch(url).then(function(r){ if(!r.ok) throw new Error(r.status); return r.json(); }); }
  var catalogP = null;
  function loadOne(pr){
    return getJSON(BASE + 'p/' + encodeURIComponent(pr.style.replace(/[^A-Za-z0-9_-]/g, '_').toUpperCase()) + '.json')
      .then(function(j){ return j && j.product; })
      .catch(function(){ return null; })
      .then(function(raw){
        if(raw) return raw;
        catalogP = catalogP || getJSON(BASE + 'products.json').catch(function(){ return {products:[]}; });
        return catalogP.then(function(d){ return (d.products || []).filter(function(x){ return String(x.style).toUpperCase() === pr.style.toUpperCase(); })[0] || null; });
      })
      .then(function(raw){ S.data[pr.style] = raw ? E.prepare(raw) : false; });
  }

  /* ---- pricing ---- */
  function cfg(p, m, qty){
    var loc = E.locations(p, m)[0], lm = {};
    lm[loc.key] = m;
    return {qty:qty, locs:[loc.key], locMethod:lm, frontColors:1, backColors:1,
            addons:{neck:false, hem:false, bag:false}, rush:'std', promoDiscount:0};
  }
  function quote(){
    var p = S.data[cur().style];
    if(!p) return null;
    if(E.decoMethods(p).indexOf(S.m) < 0) return null;
    var u = E.unitPrice(p, cfg(p, S.m, S.qty));
    if(u == null) return null;
    var next = null;
    E.priceBreaks(p, cfg(p, S.m, S.qty)).forEach(function(q){
      if(next || q <= S.qty) return;
      var nu = E.unitPrice(p, cfg(p, S.m, q));
      if(nu != null && nu < u - 0.005) next = {q:q, u:nu};
    });
    return {unit:u, total:+(u * S.qty).toFixed(2), next:next};
  }

  /* ---- markup ---- */
  function tile(pr, i){
    return '<button type="button" class="alp-tile" role="radio" aria-checked="' + (i === S.p) + '" data-p="' + i + '">' +
      '<img src="' + imgUrl(pr) + '" alt="" width="100" height="80" loading="eager"><span>' + esc(pr.label) + '</span>' +
      '<span class="alp-check" aria-hidden="true">&#10003;</span></button>';
  }
  function decoBtns(){
    return cur().methods.map(function(m){
      return '<button type="button" class="alp-deco" role="radio" aria-checked="' + (m === S.m) + '" data-m="' + m + '">' + MLABEL[m] + '</button>';
    }).join('');
  }
  function mount(){
    var pr = cur();
    root.innerHTML =
      '<img class="alp-logo" src="' + BASE + 'media/landing/alive-logo-white.svg" alt="Alive Print Shop" width="154" height="64">' +
      '<div class="alp-grid"><div class="alp-ctl">' +
        '<h1>What are we making?</h1>' +
        '<div class="alp-sec alp-products"><span class="alp-lbl" id="alp-pl">Product</span><div class="alp-row" role="radiogroup" aria-labelledby="alp-pl">' + PRODUCTS.map(tile).join('') + '</div></div>' +
        '<div class="alp-sec alp-qty"><label class="alp-lbl" for="alp-q">How many?</label><div class="alp-qrow"><div class="alp-step">' +
          '<button type="button" data-minus aria-label="Decrease quantity">&minus;</button>' +
          '<input id="alp-q" type="number" inputmode="numeric" min="' + CONFIG.min + '" step="1" value="' + S.qty + '" aria-describedby="alp-min alp-err">' +
          '<button type="button" data-plus aria-label="Increase quantity">+</button></div><span id="alp-min">Minimum ' + CONFIG.min + '</span></div></div>' +
        '<div class="alp-sec alp-decos"><span class="alp-lbl" id="alp-dl">Decoration</span><div class="alp-row" role="radiogroup" aria-labelledby="alp-dl" data-decos>' + decoBtns() + '</div></div>' +
        '<div class="alp-price loading" aria-live="polite" data-price></div>' +
        '<div class="alp-acts"><button type="button" class="alp-go" data-go="design">Start Designing <span aria-hidden="true">&rarr;</span></button>' +
          '<p class="alp-err" id="alp-err" role="alert" hidden></p>' +
          '<ul class="alp-perks"><li>No setup fees</li><li>Proof before we print</li><li>100% print guarantee</li></ul></div>' +
      '</div>' +
      '<figure class="alp-fig"><div class="alp-photo"><img data-photo src="' + imgUrl(pr) + '" alt="" width="600" height="620"></div>' +
        '<figcaption class="alp-cap" data-cap aria-live="polite"></figcaption></figure></div>';
    wire(); update();
  }
  function validQty(){ var raw = String(qtyEl().value).trim(); return /^\d+$/.test(raw) && +raw >= CONFIG.min && +raw <= 100000; }
  function qtyEl(){ return root.querySelector('#alp-q'); }
  function showErr(t){ var e = root.querySelector('#alp-err'); e.textContent = t || ''; e.hidden = !t; qtyEl().setAttribute('aria-invalid', t ? 'true' : 'false'); }
  function update(){
    var pr = cur();
    root.querySelectorAll('.alp-tile').forEach(function(b){ b.setAttribute('aria-checked', String(+b.getAttribute('data-p') === S.p)); });
    root.querySelector('[data-decos]').innerHTML = decoBtns();
    root.querySelectorAll('[data-m]').forEach(function(b){ b.onclick = function(){ S.m = b.getAttribute('data-m'); update(); }; });
    var img = root.querySelector('[data-photo]');
    if(img.getAttribute('src') !== imgUrl(pr)) img.src = imgUrl(pr);
    img.alt = 'Black ' + pr.brand + ' ' + pr.style + ' ' + pr.noun;
    root.querySelector('[data-cap]').textContent = pr.brand + ' · ' + pr.style + ' · ' + CONFIG.color;
    root.querySelector('[data-minus]').disabled = !validQty() || +qtyEl().value <= CONFIG.min;
    priceBox();
  }
  function priceBox(){
    var el = root.querySelector('[data-price]'), pr = cur(), d = S.data[pr.style];
    if(d === undefined){ el.className = 'alp-price loading'; el.innerHTML = '<div class="alp-unit">&nbsp;</div><div class="alp-total">&nbsp;</div><div class="alp-sub">Getting your price&hellip;</div>'; return; }
    el.className = 'alp-price';
    if(!validQty()){ el.innerHTML = '<div class="alp-sub" style="margin:0">Enter ' + CONFIG.min + ' or more to see your price.</div>'; return; }
    var q = d ? quote() : null;
    if(!q){ el.innerHTML = '<div class="alp-sub" style="margin:0">Pricing for this item is on the next step.</div>'; return; }
    el.innerHTML = '<div class="alp-unit">' + money(q.unit) + ' <small>/ ' + pr.noun + '</small></div>' +
      '<div class="alp-total">' + money(q.total) + '<span>for ' + S.qty.toLocaleString('en-US') + '</span></div>' +
      '<div class="alp-sub">' + MNOTE[S.m] + ' included' +
        (q.next ? ' &middot; <button type="button" class="alp-nudge" data-next="' + q.next.q + '">' + q.next.q + '+ drops to ' + money(q.next.u) + '</button>' : '') + '</div>';
    var nb = el.querySelector('[data-next]');
    if(nb) nb.onclick = function(){ S.qty = +nb.getAttribute('data-next'); qtyEl().value = S.qty; showErr(''); update(); track('landing_price_break', {qty:S.qty, style:pr.style}); };
  }
  function go(intent){
    if(!validQty()){ showErr('Please enter a whole number of ' + CONFIG.min + ' or more.'); qtyEl().focus(); return; }
    var pr = cur(), q = quote();
    var url = new URL(CONFIG.productPage, window.location.href);
    url.searchParams.set('style', pr.style);
    url.searchParams.set('color', CONFIG.color);
    url.searchParams.set('qty', String(S.qty));
    url.searchParams.set('method', S.m);
    url.searchParams.set('intent', intent);
    track('landing_continue', {intent:intent, style:pr.style, qty:S.qty, method:S.m, value:q ? q.total : 0, currency:'USD'});
    window.location.assign(url.href);
  }
  function wire(){
    root.querySelectorAll('[data-p]').forEach(function(b){ b.onclick = function(){
      S.p = +b.getAttribute('data-p');
      if(cur().methods.indexOf(S.m) < 0) S.m = cur().methods[0];
      update(); track('landing_product', {style:cur().style});
    }; });
    var q = qtyEl();
    q.addEventListener('input', function(){ if(validQty()){ S.qty = +q.value; showErr(''); } update(); });
    q.addEventListener('blur', function(){ if(!validQty()) showErr('Please enter a whole number of ' + CONFIG.min + ' or more.'); });
    root.querySelector('[data-plus]').onclick = function(){ S.qty = validQty() ? S.qty + 1 : CONFIG.min; q.value = S.qty; showErr(''); update(); };
    root.querySelector('[data-minus]').onclick = function(){ if(validQty() && S.qty > CONFIG.min){ S.qty--; q.value = S.qty; } showErr(''); update(); };
    root.querySelectorAll('[data-go]').forEach(function(b){ b.onclick = function(){ go(b.getAttribute('data-go')); }; });
    /* Arrow keys move between radio buttons, like a real radio group. */
    root.addEventListener('keydown', function(e){
      var t = e.target; if(!t || t.getAttribute('role') !== 'radio' || !/^Arrow/.test(e.key)) return;
      var sibs = [].slice.call(t.parentNode.querySelectorAll('[role="radio"]')), i = sibs.indexOf(t);
      var n = sibs[(i + (/Right|Down/.test(e.key) ? 1 : sibs.length - 1)) % sibs.length];
      if(n){ e.preventDefault(); n.click(); var f = root.querySelector('[' + (n.hasAttribute('data-p') ? 'data-p' : 'data-m') + '="' + (n.getAttribute('data-p') || n.getAttribute('data-m')) + '"]'); if(f) f.focus(); }
    });
  }
  mount();
  Promise.all(PRODUCTS.map(loadOne)).then(update, update);
  window.__ALIVE_LANDING__ = {S:S, quote:quote, PRODUCTS:PRODUCTS};
})();
